"""Task-led diary and shared source/product search. Runs after data integration."""
from pathlib import Path
import json,re,xml.etree.ElementTree as ET
from build_global_product import page, head, companion, e
from build_diary_catalogue import build as catalogue_build

ROOT=Path(__file__).resolve().parents[1]
SCRIPTS=['food-core.js','branded-foods.js','food-library.js','food-diary-store.js','food-app.js','food-portion-compare.js','diary-edit.js','app-runtime.js']

def repeat_dialog():
    return '''<dialog id="diary-repeat" class="food-review diary-repeat" aria-labelledby="diary-repeat-title"><form data-repeat-form>
<header class="food-review-header"><h2 id="diary-repeat-title">Repeat a meal</h2><button class="dialog-close" type="button" data-repeat-close>Close</button></header>
<div class="food-review-log-options"><label>From date<input name="sourceDate" type="date" required></label><label>From meal<select name="source" data-repeat-source></select></label></div>
<p class="food-search-hint">Reuses your saved portions, country and source values.</p>
<div data-repeat-preview class="diary-repeat-preview"></div>
<div class="food-review-log-options"><label>Add to date<input name="targetDate" type="date" required></label><label>Add to meal<select name="targetMeal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option value="Snack">Snacks</option></select></label></div>
<label class="diary-copy-notes"><input name="copyNotes" type="checkbox"> Copy private notes too</label>
<p data-repeat-warning class="food-search-hint" hidden></p>
<p data-repeat-status class="diary-message" role="status" aria-live="polite"></p>
<div class="food-actions"><button class="btn btn-primary" type="submit" data-repeat-save>Copy meal</button></div>
</form></dialog>'''

def search_ui():
    return '''<section class="food-search-region" aria-label="Find food"><form class="food-search-form" data-food-search><label class="food-query-label"><span class="sr-only">Food, brand or barcode</span><input type="search" data-food-query autocomplete="off" placeholder="Food, brand, barcode" maxlength="150"></label><button class="btn btn-primary" type="submit">Search</button></form><div class="food-search-tools"><details class="food-search-options"><summary>Filters</summary><div class="food-search-filters"><label>Source<select data-food-type><option value="">All foods</option><option value="branded">Packaged products</option><option value="restaurant">Restaurant menus</option><option value="reference">Reference foods</option></select></label><label>Market<select data-food-market></select></label><label data-restaurant-filter>Restaurant<select data-food-restaurant><option value="">All restaurants</option></select></label><label>Sort<select data-food-sort><option value="relevance">Best match</option><option value="name">Name A–Z</option></select></label></div></details></div><p class="food-status" data-food-status role="status" aria-live="polite"></p><div class="food-search-list" data-food-results></div><noscript><p>Food lookup needs JavaScript. <a href="/food-library-sources.html">Browse source information</a>.</p></noscript></section>'''

def review():
    return '''<dialog id="food-review" class="food-review" aria-labelledby="food-review-title"><form><header class="food-review-header"><div><p class="food-review-brand" data-review-brand></p><h2 id="food-review-title" data-review-title>Review food</h2></div><button class="dialog-close" type="button" data-review-close aria-label="Close food review">Close</button></header><p class="food-review-serving" data-review-serving></p><div class="food-review-amount"><label>Amount<input name="quantity" type="number" min="0.01" max="100000" step="any" value="100" required></label><label>Serving unit<select name="measure"></select></label></div><p data-review-error class="food-review-error" role="alert"></p><div data-review-values></div><div class="food-review-log-options"><label>Meal<select name="occasion"><option>Breakfast</option><option selected>Lunch</option><option>Dinner</option><option>Snack</option></select></label><details><summary>Add a private note</summary><textarea name="note" aria-label="Private note" maxlength="1000" rows="2"></textarea></details></div><details class="food-review-source"><summary>Source &amp; full nutrition</summary><p data-review-source></p><p data-review-flags></p><a data-review-link>Open source record</a><div data-review-nutrients></div><p>— means unavailable. Values describe the source food and portion, not a measurement of your exact plate.</p></details><div class="food-actions"><button class="btn btn-primary" type="submit" data-review-save>Add food</button><button type="button" data-review-ingredient>Add ingredient</button><button type="button" data-review-favorite>Save favorite</button><button type="button" data-review-compare>Compare this portion</button><a class="text-action" data-review-log href="/food-diary.html">Log this food →</a></div></form></dialog>'''

def diary():
    buddy=companion().replace('<svg','<button type="button" class="companion-wave" data-companion-wave aria-label="Wave to broccoli"><svg').replace('</svg>','</svg></button>')
    # Reuse the original layered character so hover can animate the arm itself.
    ns='{http://www.w3.org/2000/svg}';sprite=ET.parse(ROOT/'images/food-characters.svg').getroot()
    symbol=next(n for n in sprite if n.get('id')=='food-broccoli')
    svg=ET.Element(ns+'svg',{'viewBox':'0 0 160 160','aria-hidden':'true'})
    for child in symbol:svg.append(child)
    face=next(n for n in svg.iter() if n.get('class')=='food-face')
    for x in ['62','99']:face.insert(0,ET.Element(ns+'ellipse',{'cx':x,'cy':'88','rx':'4','ry':'2','fill':'#9bbd74','opacity':'.45'}))
    ET.register_namespace('',ns[1:-1])
    buddy=re.sub(r'<svg.*?</svg>',ET.tostring(svg,encoding='unicode'),buddy,count=1,flags=re.S)
    body='''<div class="food-app diary-app" data-food-app="diary"><header class="diary-header"><div><h1>Today’s food.</h1><p>One place for what you ate.</p><label class="diary-date">Date<input type="date" data-diary-date required></label></div>'''+buddy+'''</header><section class="diary-summary" aria-label="Logged nutrition"><div data-diary-totals></div><details class="diary-more-nutrients"><summary>Fiber, vitamins &amp; minerals</summary><dl class="food-nutrients" data-diary-micros></dl><p>Known subtotals include only available values. Missing data cannot establish a nutrient deficiency.</p></details></section><div class="diary-toolbar"><button class="btn btn-primary" type="button" data-diary-add>+ Add food</button><button class="text-action" type="button" data-open-recipes>Recipes</button><button class="text-action" type="button" data-open-preferences>Preferences</button></div><section class="diary-log" aria-label="Foods logged on this date"><div data-diary-entries></div><button type="button" data-diary-undo hidden>Undo removal</button></section><p class="diary-message" data-diary-status role="status" aria-live="polite"></p>
<dialog id="food-picker" class="food-picker" aria-labelledby="food-picker-title"><header class="food-review-header"><h2 id="food-picker-title">Add food</h2><button class="dialog-close" type="button" data-picker-close aria-label="Close food search">Close</button></header><div class="food-picker-tabs" role="tablist" aria-label="Food sources"><button type="button" role="tab" aria-selected="true" aria-controls="food-search-panel" id="food-tab-search" data-food-tab="search">Search</button><button type="button" role="tab" aria-selected="false" tabindex="-1" aria-controls="food-recent-panel" id="food-tab-recent" data-food-tab="recent">Recent</button><button type="button" role="tab" aria-selected="false" tabindex="-1" aria-controls="food-favorites-panel" id="food-tab-favorites" data-food-tab="favorites">Favorites</button><button type="button" role="tab" aria-selected="false" tabindex="-1" aria-controls="food-recipes-panel" id="food-tab-recipes" data-food-tab="recipes">Recipes</button><button type="button" role="tab" aria-selected="false" tabindex="-1" aria-controls="food-saved-panel" id="food-tab-saved" data-food-tab="saved">Saved orders</button></div><div id="food-search-panel" role="tabpanel" aria-labelledby="food-tab-search" data-food-panel="search">'''+search_ui()+'''<p class="food-search-hint">Search packaged products, menu items or everyday ingredients. Check the portion before adding.</p></div><div id="food-recent-panel" role="tabpanel" aria-labelledby="food-tab-recent" data-food-panel="recent" hidden><div data-diary-recent class="food-recent"></div></div><div id="food-favorites-panel" role="tabpanel" aria-labelledby="food-tab-favorites" data-food-panel="favorites" hidden><div data-diary-favorites class="food-recent"></div></div><div id="food-recipes-panel" role="tabpanel" aria-labelledby="food-tab-recipes" data-food-panel="recipes" hidden><div data-diary-recipes class="food-recent"></div><button class="text-action" type="button" data-create-recipe>Create a recipe →</button></div><div id="food-saved-panel" role="tabpanel" aria-labelledby="food-tab-saved" data-food-panel="saved" hidden><div data-diary-saved></div></div></dialog>
<dialog id="recipe-editor" class="food-picker recipe-editor" aria-labelledby="recipe-editor-title" data-recipe-panel><header class="food-review-header"><h2 id="recipe-editor-title">Your recipe</h2><button class="dialog-close" type="button" data-recipe-close aria-label="Close recipe editor">Close</button></header><form data-recipe-save class="food-recipe-form"><label>Recipe name<input name="recipeName" maxlength="120" required placeholder="My rice bowl"></label><label>Servings in the whole recipe<input name="yield" type="number" min="0.1" max="1000" step="any" value="1" required></label><div data-recipe-parts></div><button class="text-action" type="button" data-recipe-add>+ Add ingredient</button><p>Include the oil, sauces and other ingredients you want counted. Missing nutrient values stay unknown.</p><p data-recipe-status role="status"></p><button class="btn btn-primary" type="submit">Save recipe</button></form></dialog>
<dialog id="diary-preferences" class="food-picker" aria-labelledby="diary-preferences-title"><header class="food-review-header"><h2 id="diary-preferences-title">Diary preferences</h2><button class="dialog-close" type="button" data-preferences-close aria-label="Close diary preferences">Close</button></header><p>Saved in this browser. No account or cross-device sync. Export a backup before clearing browser data.</p><label class="companion-choice"><input type="checkbox" data-companion-toggle checked> Show broccoli companion</label><details><summary>Backup &amp; restore</summary><div class="food-privacy-actions"><button type="button" data-diary-export>Export diary</button><label>Import an export<input type="file" data-diary-import accept="application/json"></label></div><p>Exports include private notes. Import validates saved values before changing the diary.</p></details><details><summary>Storage &amp; offline use</summary><p data-app-offline-status></p><button type="button" data-app-update hidden>Use updated version</button><p>Previously loaded food profiles can work offline. New searches may need a connection.</p><a href="/privacy.html">Privacy details</a></details><details><summary>Delete diary</summary><p>Removes local entries, recipes and diary preferences. Saved restaurant orders are separate.</p><button class="food-destructive" type="button" data-diary-delete>Delete local diary</button></details><p class="diary-message" data-preferences-status role="status"></p></dialog></div>'''+review()
    body=body.replace('<label class="diary-date">Date<input type="date" data-diary-date required></label>','<div class="diary-date-tools"><label class="diary-date">Date<input type="date" data-diary-date required></label><nav class="diary-date-nav" aria-label="Diary day"><button type="button" data-diary-previous aria-label="Previous day"><svg viewBox="0 0 24 24" aria-hidden="true"><use href="/icon-sprite.svg#icon-arrow-right"/></svg></button><button type="button" data-diary-today>Today</button><button type="button" data-diary-next aria-label="Next day"><svg viewBox="0 0 24 24" aria-hidden="true"><use href="/icon-sprite.svg#icon-arrow-right"/></svg></button></nav></div>')
    body=body.replace('<button class="text-action" type="button" data-open-recipes>','<button class="text-action" type="button" data-repeat-open>Repeat meal</button><button class="text-action" type="button" data-open-recipes>',1)
    body=body.replace('<p class="diary-message" data-diary-status',repeat_dialog()+'<p class="diary-message" data-diary-status',1)
    meals=[('Breakfast','Breakfast'),('Lunch','Lunch'),('Dinner','Dinner'),('Snack','Snacks')]
    meal_choice='<label class="diary-meal-choice" data-picker-meals><span>Meal</span><select name="pickerMeal">'+''.join('<option value="'+value+'"'+(' selected' if value=='Lunch' else '')+'>'+label+'</option>' for value,label in meals)+'</select></label>'
    body=body.replace('<div class="food-picker-tabs"',meal_choice+'<div class="food-picker-tabs"',1)
    controls='<details class="diary-food-browse" data-food-browse-controls hidden><summary>Categories</summary><label>Food category<select data-food-browse-group></select></label><label>Preparation<select data-food-browse-preparation><option value="">All preparations</option><option value="raw">Raw</option><option value="cooked">Cooked</option></select></label><p data-food-browse-caption>Reference servings, available in every country.</p></details>'
    body=body.replace('</div><p class="food-status"',controls+'</div><p class="food-status"',1)
    body=body.replace('<div class="food-search-list" data-food-results></div>','<div class="food-search-list" data-food-results></div><button class="text-action" type="button" data-food-browse-more hidden>Show more foods</button>',1)
    body=body.replace('<option>Snack</option>','<option value="Snack">Snacks</option>')
    body=body.replace('data-food-app="diary"','data-food-app="diary" data-diary-catalogue="'+catalogue_build()+'"',1)
    body=body.replace('One place for what you ate.','Breakfast, lunch, dinner and everything between.')
    body=body.replace('Search packaged products, menu items or everyday ingredients. Check the portion before adding.','Search a food, brand or barcode, or browse the everyday foods below.')
    body=body.replace('<label>Market<select','<label>Country for menus &amp; packages<select')
    page('/food-diary.html','Private food diary: breakfast, lunch, dinner & snacks','Log breakfast, lunch, dinner and snacks. Browse everyday foods, check portions and save a private food diary that works across countries.',body,'diary',SCRIPTS[:5]+['diary-actions.js']+SCRIPTS[5:],indexable=False)

def library():
    body='<div class="food-app food-library-app" data-food-app="library">'+head('Find your food.','Ingredients, packaged products and restaurant servings, with their sources.')+'<div class="library-toolbar"><a class="text-action" href="/food-diary.html">Open your diary →</a><a class="text-action" href="/grocery-food-coverage.html">Browse brands →</a><a class="text-action" href="/food-library-sources.html">Sources &amp; coverage →</a></div>'+search_ui()+'''<section class="food-portion-comparison" data-food-comparison hidden aria-labelledby="food-comparison-title"><header class="food-review-header"><h2 id="food-comparison-title">Compare reviewed portions.</h2><button type="button" data-food-compare-clear>Clear</button></header><label>Comparison basis<select data-food-compare-basis><option value="portions">Your reviewed portions</option><option value="100g">100 g of each food</option></select></label><p data-food-compare-status role="status"></p><div data-food-compare-content></div></section><details class="food-product-details"><summary>Choosing the right record</summary><p>Match the preparation, brand, country and serving. Reference dishes describe a source recipe, not your exact homemade dish. A barcode identifies a package record; it does not prove today’s formulation or store availability.</p><a href="/raw-vs-cooked-food-weight.html">Raw versus cooked weights →</a></details></div>'''+review()
    page('/food-library.html','Food library: ingredients, brands & menu nutrition','Find food by name, brand or barcode. Check exact source portions, calories, protein, carbs, fat and available nutrients before logging.',body,'library',SCRIPTS)

def main():
    diary();library()
    # The underlying offline capability stays. No public install/AI promotion.
    for name in ['food-diary.html','food-library.html']:
        p=ROOT/name;text=p.read_text(encoding='utf-8')
        text=re.sub(r'<script[^>]+src="/?js/(?:food-assistant|app-config)\.js[^>]*>\s*</script>','',text)
        p.write_text(text,encoding='utf-8')
    p=ROOT/'privacy.html';text=p.read_text(encoding='utf-8')
    text=text.replace('Selecting a photo creates a resized local preview; it is not sent or analyzed. No microphone recording is offered while the service is disabled.','Photo, microphone and AI draft entry points are not offered while the service is disabled.')
    text=text.replace('This section updated October 11, 2026.','This section updated October 12, 2026.')
    text=text.replace('AI analysis is not connected in this release. Photo, microphone and AI draft entry points are not offered while the service is disabled.','Photo, voice and AI analysis are unavailable. The public diary does not offer recording or AI draft controls.')
    p.write_text(text,encoding='utf-8')
    print('Rebuilt task-led diary and food library; install/unfinished AI entry points removed.')
if __name__=='__main__':main()
